/* From Uiverse.io by alexmaracinaru - Tags: icon, button */
.__UIV_SCOPE__ button {
  cursor: pointer;
  font-weight: 700;
  font-family: Helvetica,"sans-serif";
  transition: all .2s;
  padding: 10px 20px;
  border-radius: 100px;
  background: #cfef00;
  border: 1px solid transparent;
  display: flex;
  align-items: center;
  font-size: 15px;
}

.__UIV_SCOPE__ button:hover {
  background: #c4e201;
}

.__UIV_SCOPE__ button > svg {
  width: 34px;
  margin-left: 10px;
  transition: transform .3s ease-in-out;
}

.__UIV_SCOPE__ button:hover svg {
  transform: translateX(5px);
}

.__UIV_SCOPE__ button:active {
  transform: scale(0.95);
}
